//! Compiles IR into JavaScript that imports bindings.

pub mod boundary;
pub mod enum_;
pub mod fn_;
pub mod imports;
pub mod mod_;
pub mod struct_;
mod validation;

use salsa::Setter;

use crate::codegen::db::Db;

/// Paths that are used to generate JavaScript glue code.
#[salsa::input(singleton)]
pub struct JsCodegenPaths {
    /// The path to the file containing the JavaScript bindings generated by the
    /// selected bindings API.
    #[returns(ref)]
    pub generated_bindings_path: String,
}

impl JsCodegenPaths {
    /// Creates or updates the active [`JsCodegenPaths`] singleton.
    pub fn set(db: &mut dyn Db, generated_bindings_path: String) -> Self {
        if let Some(paths) = Self::try_get(db) {
            paths
                .set_generated_bindings_path(db)
                .to(generated_bindings_path);
            paths
        } else {
            Self::new(db, generated_bindings_path)
        }
    }
}
